use Iterator;
use Throwable;
use Civi\Lughauth\Features\Access\User\Application\Service\Visibility\UserVisibilityService;
use Civi\Lughauth\Features\Access\RelyingParty\Application\Service\Visibility\RelyingPartyVisibilityService;
use Civi\Lughauth\Features\Access\TrustedClient\Application\Service\Visibility\TrustedClientVisibilityService;
use Civi\Lughauth\Features\Access\UserRoleAssignament\Domain\ValueObject\UserRoleAssignamentRolesListRef;
use Civi\Lughauth\Features\Access\Role\Application\Service\Visibility\RoleVisibilityService;
use Civi\Lughauth\Shared\Exception\NotFoundException;
use Civi\Lughauth\Features\Access\UserRoleAssignament\Domain\UserRoleAssignamentRef;
use Civi\Lughauth\Features\Access\UserRoleAssignament\Domain\UserRoleAssignamentAttributes;
use Civi\Lughauth\Features\Access\UserRoleAssignament\Domain\UserRoleAssignament;
use Civi\Lughauth\Features\Access\UserRoleAssignament\Domain\Gateway\UserRoleAssignamentFilter;
use Civi\Lughauth\Features\Access\UserRoleAssignament\Domain\Gateway\UserRoleAssignamentCursor;
use Civi\Lughauth\Features\Access\UserRoleAssignament\Domain\Gateway\UserRoleAssignamentReadGateway;
use Civi\Lughauth\Features\Access\UserRoleAssignament\Domain\Gateway\UserRoleAssignamentSlide;
use Civi\Lughauth\Features\Access\UserRoleAssignament\Domain\Gateway\UserRoleAssignamentWriteGateway;
use Civi\Lughauth\Shared\Observability\LoggerAwareTrait;
use Civi\Lughauth\Shared\Observability\TracerAwareTrait;

class UserRoleAssignamentVisibilityService
{
    use LoggerAwareTrait;
    use TracerAwareTrait;

    public function __construct(
        private readonly EventDispatcherInterface $dispatcher,
        private readonly UserRoleAssignamentReadGateway $readGateway,
        private readonly UserRoleAssignamentWriteGateway $writeGateway,
        private readonly UserVisibilityService $userVisibilityService,
        private readonly RelyingPartyVisibilityService $relyingPartyVisibilityService,
        private readonly TrustedClientVisibilityService $trustedClientVisibilityService,
        private readonly RoleVisibilityService $roleVisibilityService
    ) {
    }

    public function prepareVisibleDataInList(UserRoleAssignament $content): UserRoleAssignamentAttributes
    {
        return $this->prepareVisibleDataCallback($content, true);
    }
    public function prepareVisibleData(UserRoleAssignament $content): UserRoleAssignamentAttributes
    {
        return $this->prepareVisibleDataCallback($content, false);
    }
    public function copyWithFixed(UserRoleAssignamentAttributes $attributes, ?UserRoleAssignament $original = null): UserRoleAssignamentAttributes
    {
        $this->logDebug("Copy with fixed for User role assignament");
        $span = $this->startSpan("Copy with fixed for  User role assignament");
        try {
            $visible = $this->visiblesReferences($attributes);
            $fixed = $this->fieldsToFix($original);
            foreach ($fixed as $field) {
                $visible->unset($field);
            }
            $result = $this->dispatcher->dispatch(new UserRoleAssignamentPresetValues($attributes, $original));
            return $result->attributes;
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
    }

    public function copyWithHidden(UserRoleAssignamentAttributes $attributes, ?UserRoleAssignament $original = null): UserRoleAssignamentAttributes
    {
        $this->logDebug("Copy with hidden for User role assignament");
        $span = $this->startSpan("Copy with hidden for  User role assignament");
        try {
            $hidden = $this->fieldsToHide($original);
            foreach ($hidden as $field) {
                $attributes->unset($field);
            }
            return $attributes;
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
    }

    public function checkVisibility(Iterator|string|UserRoleAssignamentRef $value): bool
    {
        $this->logDebug("Check visibility of an iterator for User role assignament");
        $span = $this->startSpan("Check visibility of an iterator for  User role assignament");
        try {
            if (is_string($value)) {
                return !!$this->retrieveVisibleForUpdate(new UserRoleAssignamentRef($value));
            } elseif ($value instanceof UserRoleAssignamentRef) {
                return !!$this->retrieveVisibleForUpdate($value);
            } elseif ($value instanceof Iterator) {
                $ids = [];
                foreach ($value as $val) {
                    $ids[] = $val->uid();
                }
                $filter = new UserRoleAssignamentFilter(uids: $ids);
                return count($ids) == $this->countVisibles($filter);
            } else {
                return false;
            }
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
    }
    public function listVisibles(UserRoleAssignamentFilter $filter, ?UserRoleAssignamentCursor $cursor = null): UserRoleAssignamentSlide
    {
        $this->logDebug("List visibles for User role assignament");
        $span = $this->startSpan("List visibles for  User role assignament");
        try {
            $visibleFilter = $this->applyPreVisibilityFilter($filter);
            $result = $this->readGateway->list($visibleFilter, $cursor);
            return $result->slide(function (UserRoleAssignament $item): bool {
                return $this->evaluatePostVisibility($item);
            });
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
    }
    public function countVisibles(UserRoleAssignamentFilter $filter): int
    {
        $this->logDebug("Count visibles for User role assignament");
        $span = $this->startSpan("Count visibles for  User role assignament");
        try {
            $visibleFilter = $this->applyPreVisibilityFilter($filter);
            return $this->readGateway->count($visibleFilter);
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
    }
    public function listVisiblesForUpdate(UserRoleAssignamentFilter $filter, ?UserRoleAssignamentCursor $cursor = null): UserRoleAssignamentSlide
    {
        $this->logDebug("List visibles for update for User role assignament");
        $span = $this->startSpan("List visibles for update for  User role assignament");
        try {
            $visibleFilter = $this->applyPreVisibilityFilter($filter);
            $result = $this->writeGateway->listForUpdate($visibleFilter, $cursor);
            return $result->slide(function (UserRoleAssignament $item): bool {
                return $this->evaluatePostVisibility($item);
            });
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
    }
    public function countVisiblesForUpdate(UserRoleAssignamentFilter $filter): int
    {
        $this->logDebug("Count visibles for update for User role assignament");
        $span = $this->startSpan("Count visibles for update for  User role assignament");
        try {
            $visibleFilter = $this->applyPreVisibilityFilter($filter);
            return $this->writeGateway->countForUpdate($visibleFilter);
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
    }
    public function retrieveVisible(UserRoleAssignamentRef $ref): ?UserRoleAssignament
    {
        $this->logDebug("Retrieve visible for User role assignament");
        $span = $this->startSpan("Retrieve visible for  User role assignament");
        try {
            $filter = new UserRoleAssignamentFilter(uids: [$ref->uid()]);
            $visibleFilter = $this->applyPreVisibilityFilter($filter);
            if ($readed = $this->readGateway->retrieve($visibleFilter)) {
                return $this->evaluatePostVisibility($readed) ? $readed : null;
            } else {
                return null;
            }
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
    }
    public function retrieveVisibleForUpdate(UserRoleAssignamentRef $ref): ?UserRoleAssignament
    {
        $this->logDebug("Retrieve visible for update for User role assignament");
        $span = $this->startSpan("Retrieve visible for update for  User role assignament");
        try {
            $filter = new UserRoleAssignamentFilter(uids: [$ref->uid()]);
            $visibleFilter = $this->applyPreVisibilityFilter($filter);
            if ($readed = $this->writeGateway->retrieveForUpdate($visibleFilter)) {
                return $this->evaluatePostVisibility($readed) ? $readed : null;
            } else {
                return null;
            }
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
    }
    public function fieldsToFix(?UserRoleAssignamentRef $ref = null): array
    {
        $this->logDebug("Check fields to fix for User role assignament");
        $span = $this->startSpan("Check fields for fix for User role assignament");
        try {
            $result = $this->dispatcher->dispatch(new UserRoleAssignamentCollectNonEditableFields(UserRoleAssignament::calculatedFields(), $ref));
            return array_values(array_unique(array_merge($this->fieldsToHide($ref), $result->fields)));
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
    }

    public function fieldsToHide(?UserRoleAssignamentRef $ref = null): array
    {
        $this->logDebug("Check fields to hide for User role assignament");
        $span = $this->startSpan("Check fields to hide for  User role assignament");
        try {
            $result = $this->dispatcher->dispatch(new UserRoleAssignamentCollectNonVisibleFields([], $ref));
            return array_values(array_unique($result->fields));
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
    }

    private function visiblesReferences(UserRoleAssignamentAttributes $attributes): UserRoleAssignamentAttributes
    {
        $this->logDebug("Check visibility of parent references for User role assignament");
        $span = $this->startSpan("Check visibility of parent references for  User role assignament");
        try {
            $user = $attributes->getUser();
            if (null !== $user && !$this->userVisibilityService->checkVisibility($user)) {
                throw new NotFoundException("Unknown User " . ($user->uid() ?? 'no-id'));
            }
            $relyingParty = $attributes->getRelyingParty();
            if (null !== $relyingParty && !$this->relyingPartyVisibilityService->checkVisibility($relyingParty)) {
                throw new NotFoundException("Unknown RelyingParty " . ($relyingParty->uid() ?? 'no-id'));
            }
            $trustedClient = $attributes->getTrustedClient();
            if (null !== $trustedClient && !$this->trustedClientVisibilityService->checkVisibility($trustedClient)) {
                throw new NotFoundException("Unknown TrustedClient " . ($trustedClient->uid() ?? 'no-id'));
            }
            $roles = $attributes->getRoles();
            if (null !== $roles) {
                $this->checkVisibilityForRoles($roles);
            }
            return $attributes;
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
    }
    private function applyPreVisibilityFilter(UserRoleAssignamentFilter $filter): UserRoleAssignamentFilter
    {
        $this->logDebug("Compose visibility filter for User role assignament");
        $span = $this->startSpan("Compose visibility filter for  User role assignament");
        try {
            $result = $this->dispatcher->dispatch(new UserRoleAssignamentRestrictFilterToVisibility($filter));
            return $result->userRoleAssignamentFilter;
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
    }
    private function checkVisibilityForRoles(UserRoleAssignamentRolesListRef $items): UserRoleAssignamentRolesListRef
    {
        $this->logDebug("Copy with fixed for User role assignament");
        $span = $this->startSpan("Copy with fixed for  User role assignament");
        try {
            foreach ($items as $item) {
                if (null !== $item) {
                    $role = $item->getRole();
                    if (null !== $role && !$this->roleVisibilityService->checkVisibility($role)) {
                        throw new NotFoundException("Unknown Role " . ($role->uid() ?? 'no-id'));
                    }
                }
            }
            return $items;
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
    }
    private function evaluatePostVisibility(UserRoleAssignament $value): bool
    {
        $this->logDebug("Check if item is visible for User role assignament");
        $span = $this->startSpan("Check if item is visible for  User role assignament");
        try {
            $result = $this->dispatcher->dispatch(new UserRoleAssignamentVisibilityCheck(true, $value));
            return $result->visible;
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
    }
    private function prepareVisibleDataCallback(UserRoleAssignament $content, bool $inlist): UserRoleAssignamentAttributes
    {
        $this->logDebug("Prepare hydration to visible data for User role assignament");
        $span = $this->startSpan("Prepare hydration to visible data for User role assignament");
        try {
            $attributes = $content->toAttributes();
            $result = $this->dispatcher->dispatch(new UserRoleAssignamentEnrichForView($content, $inlist, $attributes));
            return $result->getAttributes();
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
    }
}
